-- Phase 7 — delete-route FK hardening.
--
-- Two delete routes land in this slice (entity delete, workflow delete), and
-- both would have been silent mass-deletes under the then-current FK rules.
-- Applied migrations are immutable (checksum, see
-- 20260930_phase6_evidence_fk_hardening), so this is a new migration, and
-- every statement below was generated by `prisma migrate diff` from the
-- migrations directory to schema.prisma — the drift check is the proof that
-- this migration and the schema agree.
--
--   1. canon_facts.entity_id — CASCADE became RESTRICT. A canon fact is the
--      canon record (CLAUDE.md §2.11); it must not vanish because the row
--      naming its subject was deleted, and the fact's evidence rows cascade
--      from the fact, so CASCADE here destroyed citations with nothing
--      recording why. deleteEntity (apps/api/src/services/canon.ts) maps the
--      refusal to a 409 naming the blocking facts. There is no escape: the
--      block is PERMANENT, because retraction withdraws a claim but keeps the
--      row (canon history is never destructively overwritten, §9) — the route
--      exists for unreferenced entities only.
--
--   2. canon_facts.object_entity_id — CASCADE became RESTRICT. The fact
--      survives its object too. It cannot be SET NULL: with the object
--      columns both NULL, the CanonFact_object_exactly_one CHECK would
--      reject the row.
--
--   3. workflow_runs.workflow_id — CASCADE became RESTRICT. Run history is
--      the execution audit trail (CLAUDE.md §2.11): deleting a workflow must
--      not silently destroy the record of what it did. deleteWorkflow
--      (apps/api/src/services/definitions.ts) maps the refusal to a 409.
--
--   4. workflow_runs.workflow_version_id — CASCADE became RESTRICT for the
--      same reason: the run cites the exact version it executed.
--
-- canon_proposals keeps CASCADE on both its entity FKs: a proposal is
-- uncommitted candidate canon (CLAUDE.md §2.13) and dies with its subject
-- safely. The facts are what block an entity delete.
--
-- Indexes: canon_facts_entity_id_idx and workflow_runs_workflow_version_id_idx
-- are added with the RESTRICT rules. PostgreSQL does not create an index for
-- a referencing column, so every parent-row delete would seq-scan these
-- tables without them (same rationale as 20260927_phase4_steprun_fk_indexes).

-- DropForeignKey
ALTER TABLE "canon_facts" DROP CONSTRAINT "canon_facts_entity_id_fkey";

-- DropForeignKey
ALTER TABLE "canon_facts" DROP CONSTRAINT "canon_facts_object_entity_id_fkey";

-- DropForeignKey
ALTER TABLE "workflow_runs" DROP CONSTRAINT "workflow_runs_workflow_id_fkey";

-- DropForeignKey
ALTER TABLE "workflow_runs" DROP CONSTRAINT "workflow_runs_workflow_version_id_fkey";

-- CreateIndex
CREATE INDEX "canon_facts_entity_id_idx" ON "canon_facts"("entity_id");

-- CreateIndex
CREATE INDEX "workflow_runs_workflow_version_id_idx" ON "workflow_runs"("workflow_version_id");

-- AddForeignKey
ALTER TABLE "workflow_runs" ADD CONSTRAINT "workflow_runs_workflow_id_fkey" FOREIGN KEY ("workflow_id") REFERENCES "workflows"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workflow_runs" ADD CONSTRAINT "workflow_runs_workflow_version_id_fkey" FOREIGN KEY ("workflow_version_id") REFERENCES "workflow_versions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "canon_facts" ADD CONSTRAINT "canon_facts_entity_id_fkey" FOREIGN KEY ("entity_id") REFERENCES "story_entities"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "canon_facts" ADD CONSTRAINT "canon_facts_object_entity_id_fkey" FOREIGN KEY ("object_entity_id") REFERENCES "story_entities"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
